void helperTestInitThrottler()
{
    ccxt::Exchange exchange = ccxt::Exchange(ccxt::dict {
        { std::string("id"), std::string("sampleexchange") },
        { std::string("rateLimit"), 10.8 },
    });
    // todo: assert (exchange.MAX_VALUE !== undefined);
    std::any tokenBucket = exchangeProp(exchange, std::string("tokenBucket")); // trick for uncamelcase transpilation
    assertTrue(!isEqual(tokenBucket, std::any{}));
    std::any rateLimit = exchangeProp(exchange, std::string("rateLimit"));
    assertTrue(isEqual(rateLimit, 10.8));
    assertTrue(isEqual(::getValue(tokenBucket, std::string("delay")), 0.001));
    assertTrue(isEqual(::getValue(tokenBucket, std::string("refillRate")), divide(1, rateLimit)));
    // fix decimal/integer issues across langs
    assertTrue(exchange.inArray(::getValue(tokenBucket, std::string("capacity")), ccxt::list{1, 1}));
    std::any cost = exchange.parseToNumeric(exchange.safeString2(tokenBucket, std::string("cost"), std::string("defaultCost"))); // python sync, todo fix
    assertTrue(exchange.inArray(cost, ccxt::list{1, 1}));
    assertTrue(!isTrue((inOp(tokenBucket, std::string("maxCapacity")))) || isTrue(exchange.inArray(::getValue(tokenBucket, std::string("maxCapacity")), ccxt::list{1000, 1000})));
}
void helperTestSandboxState(std::any exchange, std::any expectEnabled = true)
{
    assertTrue(!isEqual(exchange.urls, std::any{}));
    assertTrue(inOp(exchange.urls, std::string("test")));
    std::any isSandboxModeEnabled = exchangeProp(exchange, std::string("isSandboxModeEnabled"));
    if (isTrue(expectEnabled))
    {
        assertTrue(isEqual(isSandboxModeEnabled, true));
        assertTrue(isEqual(::getValue(::getValue(exchange.urls, std::string("api")), std::string("public")), std::string("https://testnet.org")));
        assertTrue(isEqual(::getValue(::getValue(exchange.urls, std::string("apiBackup")), std::string("public")), std::string("https://example.com")));
    } else
    {
        assertTrue(!isEqual(isSandboxModeEnabled, true));
        assertTrue(isEqual(::getValue(::getValue(exchange.urls, std::string("api")), std::string("public")), std::string("https://example.com")));
        assertTrue(isEqual(::getValue(::getValue(exchange.urls, std::string("test")), std::string("public")), std::string("https://testnet.org")));
    }
}
void helperTestInitSandbox()
{
    // todo: sandbox for real exchanges
    std::any opts = ccxt::dict {
        { std::string("id"), std::string("sampleexchange") },
        { std::string("options"), ccxt::dict {
            { std::string("sandbox"), false },
        } },
        { std::string("urls"), ccxt::dict {
            { std::string("api"), ccxt::dict {
                { std::string("public"), std::string("https://example.com") },
            } },
            { std::string("test"), ccxt::dict {
                { std::string("public"), std::string("https://testnet.org") },
            } },
        } },
    };
    //
    // CASE A: when sandbox is not enabled
    //
    ccxt::Exchange exchange3 = ccxt::Exchange(opts);
    helperTestSandboxState(exchange3, false);
    exchange3.setSandboxMode(true);
    helperTestSandboxState(exchange3, true);
    //
    // CASE B: when sandbox is enabled
    //
    ::setValue(::getValue(opts, std::string("options")), std::string("sandbox"), true);
    ccxt::Exchange exchange4 = ccxt::Exchange(opts);
    helperTestSandboxState(exchange4, true);
    exchange4.setSandboxMode(false);
    helperTestSandboxState(exchange4, false);
}
void helperTestInitMarket()
{
    // ############# markets ############# //
    std::any sampleMarket = ccxt::dict {
        { std::string("id"), std::string("BtcUsd") },
        { std::string("symbol"), std::string("BTC/USD") },
        { std::string("base"), std::string("BTC") },
        { std::string("quote"), std::string("USD") },
        { std::string("baseId"), std::string("Btc") },
        { std::string("quoteId"), std::string("Usd") },
        { std::string("type"), std::string("spot") },
        { std::string("spot"), true },
    };
    ccxt::Exchange exchange2 = ccxt::Exchange(ccxt::dict {
        { std::string("id"), std::string("sampleexchange") },
        { std::string("markets"), ccxt::dict {
            { std::string("BTC/USD"), sampleMarket },
        } },
    });
    assertTrue(isTrue((!isEqual(::getValue(exchange2, std::string("markets")), std::any{}))) && isTrue((!isEqual(::getValue(::getValue(exchange2, std::string("markets")), std::string("BTC/USD")), std::any{}))));
}
